from pathlib import Path
import csv,html,json
ROOT=Path(__file__).resolve().parents[1]
CSS='body{font:16px/1.7 system-ui,sans-serif;color:#294536;background:#f7f8f3;max-width:960px;margin:50px auto;padding:0 24px}h1{font-size:40px;line-height:1.2;letter-spacing:-1px}h2{margin-top:38px;font-size:24px}h3{margin-top:25px}a{color:#326349}table{border-collapse:collapse;width:100%;background:white;font-size:13px}td,th{border:1px solid #dfe7d9;padding:12px;text-align:left;vertical-align:top}th{background:#edf3e6}pre{background:#eaf0e3;padding:20px;overflow:auto;border-radius:8px}code{font-size:13px}small{color:#73816a}.callout{background:#eaf0e3;padding:20px;border-radius:8px}li{margin:8px 0}@media(max-width:600px){body{margin:25px auto;font-size:14px}h1{font-size:30px}table{display:block;overflow:auto}}'
def doc(name,title,body):
 (ROOT/'reports'/name).write_text(f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Relate</title><style>{CSS}</style><body><a href="../index.html">← Dashboard</a><p><small>RELATE / PROJECT DOCUMENTATION</small></p><h1>{title}</h1>{body}<p><small>Prepared 25 November 2026 · Data Science Major Project</small></p></body></html>')
fields=[('post_id','string, required','Unique stable post identifier. Matching exact duplicates are removed; conflicts fail.'),('content_id','string, optional','Creative library ID, e.g. C01. Leave blank for external content. Do not use a demo ID for unrelated creative.'),('title, topic, platform','strings, required','Human-readable dimensions. Consistent spelling is required.'),('published_at','YYYY-MM-DD','Publication date in a single, documented campaign timezone. Date filters select post cohorts, not event-time engagement.'),('format, hook','strings, required','Creative format and actual hook category.'),('variant, experiment_id','A or B plus ID, or both blank','Use a unique experiment ID per matched pair. More than one record per variant is excluded from A/B analysis.'),('duration_seconds','integer ≥ 0','Video duration; use 0 only for genuinely non-video content.'),('views, reach','integers ≥ 0','Views may include repeat plays. Reach is post-level unique reach, summed across posts; never substitute impressions for reach.'),('likes, comments, shares, saves','integers ≥ 0','Reported performance counts at the observation window. These are not deduplicated people. Zero means observed zero, not unavailable.'),('followers_gained','integer ≥ 0','Post-attributed follower gains, not net account follower change.'),('retention_rate','number from 0 to 1','Completion/retention fraction. Document the same definition across compared platforms.'),('observation_hours','positive integer','Post age when performance was measured. Demo uses 168 hours.'),('source','string','Importer assigns synthetic_demo or user_import. Keep the original export/source notes separately.')]
rows=''.join(f'<tr><td><code>{a}</code></td><td>{b}</td><td>{c}</td></tr>' for a,b,c in fields)
doc('methodology.html','Methodology & data dictionary',f'''<div class="callout"><strong>Demonstration, not a real campaign.</strong> The bundled records are generated with seed 42. No social accounts were scraped, no content was published, and no real audience outcomes are claimed.</div>
<h2>Architecture</h2><p>CSV exports → validation and cleaning → trained NLP classification → structured JSON → browser analytics → strategy and downloadable reports. The Python pipeline and the browser importer use the same schema and model. The dashboard has no external runtime dependencies, trackers or account credentials.</p>
<h2>Metrics</h2><ul><li><strong>Engagement:</strong> (likes + reported comments + shares + saves) / total post reach. Weighted by denominators, not a mean of post percentages.</li><li><strong>Weighted viral score:</strong> 100 × (3 × shares + 2 × saves + likes) / reach. Project-defined weights, not a validated virality probability or reproduction coefficient.</li><li><strong>Relatability:</strong> model-labeled Relatable comments / analyzed comments. Neutral includes questions, criticism and non-relatable reactions, not just neutral emotional valence.</li><li><strong>Save-to-share ratio:</strong> saves / shares. Undefined at zero shares.</li><li><strong>Growth:</strong> sum of post-attributed follower gains. The chart is cumulative within the selected publication cohort. It is not net account growth.</li><li><strong>Retention:</strong> view-weighted mean of retention_rate.</li><li><strong>Comment coverage:</strong> analyzed comments / reported comments. It can exceed 100% if mismatched export windows are supplied; investigate before interpretation.</li><li>Zero denominators display “—”. Missing numeric inputs are rejected rather than replaced with zero.</li></ul>
<h2>Posts CSV</h2><p>One record per post at one fixed age. Supply every column below; optional string values may be blank. Do not import repeated snapshots as separate posts. Keep raw exports intact before mapping fields.</p><table><tr><th>Field</th><th>Type</th><th>Meaning</th></tr>{rows}</table>
<h2>Comments CSV</h2><table><tr><th>Field</th><th>Meaning</th></tr><tr><td>comment_id</td><td>Unique pseudonymous ID. Repeated text from different IDs is retained.</td></tr><tr><td>post_id</td><td>Must match a post record. Orphans cause the entire import to fail.</td></tr><tr><td>text</td><td>Comment text. Unicode and whitespace are normalized and URLs removed; empty rows are dropped.</td></tr><tr><td>created_at</td><td>Valid YYYY-MM-DD date. This does not drive the cohort filters, which use the linked post's publication date.</td></tr><tr><td>source</td><td>Assigned by importer.</td></tr><tr><td>label, score, review, reason</td><td>Output fields recalculated by the model. score is the Relatable model score, not confidence in the selected class; review flags uncertainty or low vocabulary coverage. reason lists discriminative recognized features, not a causal explanation.</td></tr></table><p>A header-only comments CSV is accepted for a campaign with no collected comments. Include comment_id, post_id, text and created_at headers.</p>
<h2>Weekly trends CSV (optional)</h2><p>Columns: <code>topic,week,index,source</code>. Use one row per topic and week. week is YYYY-MM-DD, index is a number in [0,100]. Keep the same normalization, geography and source for an entire series; preserve those settings in your source notes. The importer does not fetch external trend services.</p>
<h2>Import and cleaning</h2><p>Import one JSON bundle with <code>meta, posts, comments, trends</code>, or upload CSV files together in Data Studio. All files stay in browser memory and reset on refresh. Export Full JSON to preserve the imported campaign. Limits: 15 MB per file, 10,000 posts and 50,000 comments. Identical IDs are deduplicated; conflicting IDs fail atomically. The previous dataset stays active on failure. Dynamic text is HTML-escaped and CSV exports escape formula-leading text.</p><p>Use ISO dates and decimal points without thousands separators. Do not replace missing platform metrics with zero. Map only supported measurements, or extend the schema to preserve unavailable values before making platform comparisons. Header-only templates are provided in <code>data/templates/</code> in the full source package.</p>
<h2>The NLP model</h2><p>Multinomial naive Bayes with word unigrams and bigrams, additive smoothing α=1, equal learned class priors from a balanced corpus and decision threshold 0.5. The model has 120 authored training examples and 36 fixed, separately authored test examples. Training and evaluation comments are not campaign comments. No external data or model downloads are required.</p><p>Accuracy: 88.9%; Relatable precision: 85.0%; recall: 94.4%; F1: 0.895. Confusion matrix: 15 true Neutral, 3 false Relatable, 17 true Relatable, 1 false Neutral. The small authored holdout is not a real-world benchmark. The four errors are preserved in <a href="../models/evaluation.json">evaluation.json</a>.</p><p>English only. Negation, sarcasm, mixed-language content, unfamiliar vocabulary and correlated templates are limitations. The posterior score is not calibrated. Comments with score within 0.2 of 0.5 or less than 35% known features are flagged for review. An input with no recognized English features receives Neutral, score 0.5 and review=true. High scores can still be wrong.</p>
<h2>Statistical methods</h2><p><strong>Intervals:</strong> 95% Wilson intervals for model label proportions. They omit classification error and comment clustering. They are descriptive, not proof of audience-wide differences.</p><p><strong>A/B:</strong> one A and one B for each experiment ID, with matching content_id, topic, platform, format, duration and observation window. Outcome is shares/reach. Pair differences are equally weighted. At least three pairs are required. A two-sided sign-flip permutation test enumerates all assignments up to 16 pairs, then uses 10,000 seeded samples with a plus-one correction. The 95% interval is a 2,000-resample percentile bootstrap over pairs. The test and interval use different approximations and can disagree near a threshold; the preselected permutation p-value drives the displayed conclusion. No multiple-outcome testing is performed.</p><p><strong>Forecast:</strong> OLS interest index against elapsed days, extrapolated seven days and clipped to [0,100]. At least four weekly observations. A last-point backtest is an error diagnostic, not a calibrated confidence interval. Platform filters do not apply to topic-level external trends.</p><p><strong>Recommendations:</strong> rank topics by the fraction of analyzed comments labeled Relatable. Show observed highest-scoring post format as a candidate for testing, not an optimum. Duration, caption and posting-time causal effects are not identifiable in this demo. Organic data is observational.</p>
<h2>Scope relative to the brief</h2><p>The project implements performance ingestion, weighted virality metrics, NLP, matched A/B comparisons, recommendations, interactive visualization and trend extrapolation. It uses a deployable browser dashboard instead of Power BI/Tableau/Streamlit. CSV export ingestion is implemented; live authenticated social APIs and scheduling are not connected. Video scripts and finished social cards are supplied; video filming, publication and real campaign measurement remain future fieldwork.</p>''')
doc('deployment.html','Deploy your dashboard','''<div class="callout">The dashboard is a static website. No API key, database, server function or paid service is required to run the included demo. All fonts and assets are local or system-provided.</div><h2>Fastest path: upload the ready build</h2><ol><li>Unzip <strong>relate-dashboard-deploy.zip</strong>.</li><li>Upload its contents to any static web host. <strong>index.html must be at the site's root.</strong></li><li>Open the hosted URL. Check all six views and a report download.</li></ol><p>The archive contains the dashboard, demo data, model, creative assets, PDFs and documentation. It can also be hosted in a subdirectory because asset paths are relative.</p><h2>Build from source</h2><p>Unzip <strong>relate-complete-project.zip</strong> and open a terminal in <code>relate-analytics</code>.</p><pre>npm run build\nnpm start</pre><p>Open <a href="http://127.0.0.1:5174">http://127.0.0.1:5174</a>. The build needs Node.js 22+ and the preview command needs Python 3.10+. There are no npm dependencies to install. You can also serve <code>dist/</code> with any static web server. Double-clicking index.html will not work because browsers restrict local-file fetches.</p><h2>Host settings</h2><table><tr><th>Setting</th><th>Value</th></tr><tr><td>Project root</td><td>relate-analytics (if hosted inside a larger repository)</td></tr><tr><td>Build command</td><td>npm run build</td></tr><tr><td>Output directory</td><td>dist</td></tr><tr><td>Environment variables</td><td>None</td></tr><tr><td>Routing</td><td>Hash navigation; no SPA rewrite required</td></tr></table><h2>Use real data</h2><p>Open Data Studio and import CSV exports or a JSON bundle. The imported data is temporary browser memory. Export the full JSON bundle before refreshing or leaving. No data is transmitted to a backend.</p><p>To replace the hosted default dataset, run the Python pipeline, review its output, rebuild and redeploy:</p><pre>python3 python/pipeline.py --input /path/to/exports --output data/clean --source user_import\nnpm run build</pre><p><strong>Files in a public static deployment are public.</strong> Use synthetic or appropriately anonymized records as the bundled default. Local imports are not uploaded. The PDF strategy report and content playbook describe the original demo; after importing new data, use “Export this analysis” in Strategy to download the current results.</p><h2>Verification</h2><pre>npm test</pre><p>Tests cover cleaning, invalid imports, zero denominators, sentiment parity between Python and JavaScript, exact permutation behavior, forecasts and CSV round-trips. Browser checks are documented in the project validation report.</p><h2>Rebuild every deliverable</h2><pre>python3 python/create_corpus.py\npython3 python/sentiment.py --train\npython3 python/generate_demo.py\npython3 python/pipeline.py --source synthetic_demo\nnode python/analysis.mjs\npython3 -m pip install -r requirements-reports.txt\npython3 python/make_reports.py\npython3 python/make_docs.py\nnpm test\nnpm run build\npython3 python/package_project.py</pre><p>The demo-generation command replaces generated demo files; do not run it over your only copy of real data. Keep original exports separately.</p>''')
(ROOT/'data/templates').mkdir(exist_ok=True)
for key in ['posts','comments','trends']:
 with (ROOT/f'data/raw/{key}.csv').open() as f:header=next(csv.reader(f))
 with (ROOT/f'data/templates/{key}.csv').open('w',newline='') as f:csv.writer(f).writerow(header)
print('Created methodology, deployment guide and CSV templates.')
